  beforeEach(() => {
    jest.clearAllMocks();
  });

  test('authenticates user successfully', async () => {
    const userId = 'test_user_id';
    const password = 'test_pass';
    mockStore.setUser({ id: userId, password });

    await signIn(userId, password, mockStore);

    expect(mockStore.getUser()).toBe(userId);
    expect(mockStore.rememberMe()).toBeTruthy();
  });

  test('signs out user and resets session', async () => {
    await signOut(mockStore);

    expect(mockStore.getUser()).toBe(null);
    expect(mockStore.rememberMe()).toBeFalsy();
  });
});

